<?php require __DIR__.'/includes/bootstrap.php';if(is_post()){verify_csrf();if(!user())redirect('/login.php');$pid=(int)post('product_id');db()->prepare('INSERT OR IGNORE INTO wishlists(user_id,product_id) VALUES(?,?)')->execute([user()['id'],$pid]);flash('success','Saved to wishlist.');redirect('/wishlist.php');}$items=[];if(user()){$st=db()->prepare('SELECT p.*,c.name category_name FROM wishlists w JOIN products p ON p.id=w.product_id JOIN categories c ON c.id=p.category_id WHERE w.user_id=? ORDER BY w.id DESC');$st->execute([user()['id']]);$items=$st->fetchAll();}$title='Wishlist';require __DIR__.'/includes/header.php';?><div class="max-w-6xl mx-auto px-3 sm:px-5 py-10"><div class="flex justify-between items-end mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">WISHLIST</div><h1 class="text-3xl font-black">Saved Products</h1></div><?php if(!user()):?><a href="/login.php" class="px-4 py-2 rounded-xl bg-slate-950 text-white font-bold">Login</a><?php endif;?></div><?php if($items):?><div class="grid grid-cols-2 md:grid-cols-4 gap-4"><?php foreach($items as $p):include __DIR__.'/includes/product_card.php';endforeach;?></div><?php else:?><div class="bg-white border rounded-2xl py-20 text-center text-slate-500">No saved products.</div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
